/* Victory Park v3. Local teaching prototype: no payment, sending or analytics. */
(() => {
'use strict';
const PROMO='vp.family.v3.promotion';
const KEY='vp.family.v3', ORDER='vp.family.v3.order', LOCK='vp.family.v3.payment';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v)), money=n=>new Intl.NumberFormat('ru-RU').format(n||0)+' AMD';
const btn=(act,label,data='',cls='btn')=>`<button type="button" class="${cls}" data-action="${act}" ${data}>${label}</button>`;
const note=(s,tone='info')=>`<div class="notice" data-tone="${tone}">${esc(s)}</div>`;
let state,order=null,warning='',familyOpen=false,focusPerson='family',undo=null,busy=false,activeProduct='single',customTarget='',storageAvailable=true,agePerson='',directEntry=false,returnMode='';
let formError='',copyStatus='',scenario='success',promotion=VPC.normalizePromotion(null),ticketPersonId='',accompaniment=null;
try{promotion=VPC.normalizePromotion(JSON.parse(localStorage.getItem(PROMO)||'null'));}catch{}
try {state=VP3.sanitizeState(JSON.parse(localStorage.getItem(KEY)||'null'));} catch {state=VP3.emptyState();storageAvailable=false;warning='Браузер не сохранил выбор. Можно продолжить в этой вкладке.';}
try {const raw=JSON.parse(localStorage.getItem(ORDER)||'null');if(raw){order=VPC.validateOrder(raw);if(!order)warning='Сохранённый образец заказа повреждён. Соберите заказ заново.';}}catch {warning='Предыдущий демо-заказ недоступен. Реальных списаний не было.';}
familyOpen=!state.party.length;
const rides=()=>state.mode==='real'?VP3.realRides:VP3.demoRides;
const ride=id=>[...VP3.realRides,...VP3.demoRides].find(r=>r.id===id);
const person=id=>state.party.find(p=>p.id===id);
const selected=()=>state.selections[state.mode]||[];
const ageLabel=p=>p.role==='adult'?'18+':p.age===null?'Возраст не указан':p.age===0?'До года':p.age+' лет';
const personLabel=p=>p.label+' · '+ageLabel(p);
const pickerReturn=()=>returnMode==='real'?'attractions.html?mode=real#plan':'attractions.html#plan';
const id=()=> 'v3-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2,8));
function announce(text){$('#announce').textContent=text;}
function save(){try {localStorage.setItem(KEY,JSON.stringify(state));}catch {storageAvailable=false;warning='Выбор не сохраняется в браузере. При переходе или обновлении он может потеряться.';}}
function savePromotion(){try{localStorage.setItem(PROMO,JSON.stringify(promotion));}catch{storageAvailable=false;warning='Предложение сохранено только в этой вкладке.';}}
function saveOrder(){try {if(order)localStorage.setItem(ORDER,JSON.stringify(order));else localStorage.removeItem(ORDER);}catch {storageAvailable=false;warning='Заказ доступен только в этой вкладке. Сохраните образцы сразу после выдачи.';}}
function update(message){save();render();if(message)announce(message);}
function jump(selector){requestAnimationFrame(()=>$(selector)?.scrollIntoView({block:'start',behavior:'smooth'}));}
function syncCompanions(){if(order||!VP3.reconcileCompanions)return;accompaniment=VP3.reconcileCompanions(state);state=accompaniment.state;}
function audience(){const people=focusPerson==='family'||focusPerson==='all'?state.party:[person(focusPerson)].filter(Boolean);return people;}
function admission(r,p){return VP3.admission?VP3.admission(r,p):{status:VP3.ageHint(r,p).status==='outside'?'blocked':'unknown',reasons:[]};}
function admissionMarkup(r){
  if(!r.fictional)return '';
  const people=audience(),checks=people.map(p=>({p,a:admission(r,p)})),accompanied=checks.filter(x=>x.a.needsCompanion&&x.a.status!=='blocked'),pending=checks.filter(x=>x.a.priceNeedsHeight),unknown=checks.filter(x=>x.a.status==='unknown'&&!x.a.needsCompanion);
  return `${accompanied.length?`<div class="companion-badge"><span aria-hidden="true">18+</span><strong>Только со взрослым 18+</strong></div>${people.length>1?`<p class="admission-note">Для ${accompanied.map(x=>esc(x.p.label)).join(', ')}. Взрослое катание оплачивается.</p>`:'<p class="admission-note">Взрослое катание оплачивается.</p>'}`:''}${pending.length?`<p class="admission-note">${pending.map(x=>esc(x.p.label)).join(', ')}: уточните рост, чтобы понять, нужен ли взрослый.</p>`:''}${!accompanied.length&&!pending.length&&unknown.length?'<p class="admission-note">Часть условий ещё нужно уточнить. Подробности ниже.</p>':''}`;
}
function isRequiredLine(line){if(line.autoCompanion)return true;if(!line.personId||person(line.personId)?.role!=='adult')return false;const draft=clone(state);draft.cart.lines=draft.cart.lines.filter(l=>l.id!==line.id);return VP3.reconcileCompanions(draft).additions.some(l=>l.personId===line.personId&&l.productId===line.productId&&l.rideId===line.rideId);}
function purchasePeople(){const pass=activeProduct==='unlimited';return `<div class="purchase-people" id="purchase-people"><div class="recipient-head"><h3>${pass?'Кому нужен безлимит?':'Для кого выбираем билеты?'}</h3><p class="helper">${pass?'Личное право на день. Необходимого взрослого включим автоматически.':'Один выбор для следующих билетов. Сопровождение учтём сами.'}</p></div>${state.party.length?`<div class="chips recipient-choices" role="group" aria-label="${pass?'Получатели безлимитов':'Получатель билетов'}">${state.party.map(p=>{const chosen=state.cart.lines.find(l=>l.productId==='unlimited'&&l.personId===p.id),auto=chosen&&isRequiredLine(chosen);return btn(pass?'direct-pass':'ticket-person',`${esc(p.label)} · ${esc(ageLabel(p))}${pass?'<span class="recipient-product-state">'+(auto?'Включён для сопровождения':chosen?'✓ В заказе':'Добавить')+'</span>':''}`,`data-person="${p.id}" aria-pressed="${pass?Boolean(chosen):ticketPersonId===p.id}" ${auto?'disabled':''}`,'chip');}).join('')}</div>`:''}<div class="btn-row">${btn('purchase-add-adult','+ Взрослый 18+',state.party.length>=8?'disabled':'','btn btn-outline')}${btn('purchase-add-child','+ Ребёнок',state.party.length>=8?'disabled':'','btn btn-outline')}</div>${person(ticketPersonId)?.role==='child'?`<div class="purchase-child-age">${agePicker(person(ticketPersonId))}</div>`:''}</div>`;}
function contextFixes(issues=[]){
  const rows=issues.filter(i=>i.code==='child-age-required'||i.code==='height-required'),seen=new Set();
  return rows.map(i=>{const p=person(i.personId);if(!p)return '';const key=i.code+':'+p.id;if(seen.has(key))return '';seen.add(key);return i.code==='child-age-required'&&p.id===ticketPersonId&&activeProduct!=='package'?`<p class="context-fix"><a class="btn btn-outline" href="#age-${p.id}">Выбрать возраст: ${esc(p.label)}</a></p>`:i.code==='child-age-required'?`<div class="context-fix"><strong>${esc(p.label)}: выберите возраст</strong>${agePicker(p)}</div>`:`<div class="context-fix"><label for="purchase-height-${p.id}"><strong>${esc(p.label)}: какой рост?</strong></label><p class="helper">От этого зависит, нужен ли оплаченный билет взрослому.</p><div class="height-input"><input id="purchase-height-${p.id}" data-field="height" data-person="${p.id}" data-ride="${esc(i.rideId||'demo-calm')}" inputmode="decimal" value="${p.height??''}" placeholder="Рост в см" aria-describedby="height-error-purchase-${p.id}"><span>см</span></div><span id="height-error-purchase-${p.id}" class="field-error" role="status"></span></div>`;}).join('');
}
function companionControls(extraIssues=[]){
  const issues=[...(accompaniment?.issues||[]),...extraIssues],needed=state.cart.lines.some(l=>l.autoCompanion)||issues.some(i=>i.code.startsWith('companion-'))||Boolean(accompaniment?.requiredAdultId),adults=state.party.filter(p=>p.role==='adult'&&(p.age===null||p.age>=18)),chosen=person(state.companionId),fixes=contextFixes(issues);
  if(!needed&&!fixes)return '';
  return `<section class="companion-controls" id="companion-controls" aria-labelledby="companion-heading">${needed?`${chosen&&adults.length===1?`<p id="companion-heading"><strong>Сопровождающий: ${esc(chosen.label)} · 18+</strong></p>`:`<h3 id="companion-heading">Кто сопровождает детей?</h3>`}${state.party.filter(p=>p.role==='child').length>1?'<p class="helper">Один взрослый, дети катаются с ним по очереди.</p>':''}${adults.length>1?`<div class="chips" role="group" aria-label="Сопровождающий взрослый">${adults.map(p=>btn('choose-companion',esc(p.label)+' · 18+',`data-person="${p.id}" aria-pressed="${state.companionId===p.id}"`,'chip')).join('')}</div>`:''}${!adults.length?btn('purchase-add-companion','Добавить взрослого 18+',state.party.length>=8?'disabled':'','btn btn-outline'):''}${issues.filter(i=>i.code==='companion-unavailable').map(i=>note(i.message,'error')).join('')}`:''}${fixes}</section>`;
}
function agePicker(p){if(p.role==='adult')return '';const open=agePerson===p.id;return `<div class="child-age">${btn('edit-age',`<span>${p.age===null?'Выбрать возраст':esc(ageLabel(p))}</span><span>${open?'Свернуть':'Изменить'}</span>`,`id="age-${p.id}" data-person="${p.id}" aria-expanded="${open}" aria-controls="age-panel-${p.id}"`,'age-summary')}${open?`<div class="age-panel" id="age-panel-${p.id}" role="group" aria-label="Возраст: ${esc(p.label)}"><div class="age-grid">${Array.from({length:18},(_,n)=>btn('choose-age',n===0?'До года':String(n),`data-person="${p.id}" data-value="${n}" aria-label="${n===0?'До года':n+' лет'}" aria-pressed="${p.age===n}"`,'age-choice')).join('')}${btn('choose-age','Не знаю',`data-person="${p.id}" data-value="unknown" aria-pressed="${p.age===null}"`,'age-choice age-unknown')}</div></div>`:''}</div>`;}
function family(){return `<details class="family-panel" id="family" ${familyOpen?'open':''}><summary><span>${state.party.length?esc(state.party.map(personLabel).join(' / ')):'Кто идёт в парк?'}</span><span class="family-edit">${state.party.length?'Изменить':'Добавить семью'}</span></summary><p class="family-intro">Добавьте взрослых и детей. Детям выберите возраст, если знаете.</p><div class="party">${state.party.map((p,i)=>`<article class="person" id="person-${p.id}"><div class="person-head"><span class="avatar" aria-hidden="true">${i+1}</span><h3>${esc(p.label)}</h3>${p.role==='adult'?'<span class="adult-age"><strong>18+</strong></span>':''}${btn('remove-person','×',`data-person="${p.id}" aria-label="Убрать ${esc(p.label)}"`,'btn btn-text remove-person')}</div>${agePicker(p)}</article>`).join('')}</div><div class="btn-row">${btn('add-adult','+ Взрослый',state.party.length>=8?'disabled':'')}${btn('add-child','+ Ребёнок',state.party.length>=8?'disabled':'')}${btn('collapse-family',state.party.length?'Готово':'Смотреть все','','btn btn-dark')}</div></details>`;}
function catalogModes(){return `<div class="chips catalog-modes" role="group" aria-label="Каталог аттракционов">${btn('mode','Аттракционы парка',`data-mode="real" aria-pressed="${state.mode==='real'}"`,'chip')}${btn('mode','Учебный подбор',`data-mode="demo" aria-pressed="${state.mode==='demo'}"`,'chip')}</div>`;}
function demoTools(){return `<details class="demo-tools" id="demo-tools"><summary>О прототипе и данных</summary><p>Фотографии в блоках знакомства с парком настоящие. Учебные карточки используют фотографии парка и сгенерированные иллюстрации с отдельными подписями. Цены и правила служат вымышленными примерами. Образцы не действуют для посещения.</p>${document.body.dataset.page==='picker'?'':catalogModes()}<p class="helper">У настоящих аттракционов не подтверждены возрастные ориентиры, категории и ростовые ограничения. Они доступны для просмотра и сохранения.</p><div class="btn-row">${btn('sample','Пример: двое взрослых и дети 6 и 11 лет','','btn btn-text')}${btn('reset-state','Очистить мой выбор','','btn btn-text')}</div>${undo?.kind==='sample'?undoBanner():''}</details>`;}
function hero(kind){const picker=kind==='picker';return `<section class="hero v3-hero"><div class="hero-copy"><p class="eyebrow">${picker?'Ваш день в Victory Park':'Меньше считать. Больше кататься.'}</p><h1>${picker?'Всем найдётся<br><span>своё приключение</span>':'Билеты для<br><span>вашей семьи</span>'}</h1><p>${picker?'Укажите возраст, посмотрите развлечения и сохраните то, что хочется попробовать.':'Выберите, кто катается, и сравните готовые варианты. Или соберите свой заказ.'}</p>${!picker?'<a class="btn btn-text" href="attractions.html#plan">← К нашим аттракционам</a>':''}</div><figure class="hero-photo"><img src="assets/${picker?'wheel-of-happiness':'autodrom'}.webp" width="700" height="440" fetchpriority="high" alt="${picker?'Колесо счастья':'Автодром'} Victory Park"><figcaption>Настоящее фото парка</figcaption></figure></section>`;}
function displayedRides(){const list=rides();if(state.mode==='real'||focusPerson==='all'||!state.party.length)return list;const people=audience();if(!people.length)return list;return list.filter(r=>people.some(p=>admission(r,p).status!=='blocked'));}
function ageText(r){if(!r.fictional)return 'Правила допуска пока уточняются';const people=audience();if(!people.length)return 'Выберите возраст ребёнка, чтобы увидеть условия';const solo=people.filter(p=>admission(r,p).status==='solo');if(solo.length)return solo.map(p=>p.label).join(', ')+': самостоятельно по учебным правилам';if(people.every(p=>admission(r,p).status==='blocked'))return 'Пока не подходит выбранным участникам';const possible=people.filter(p=>admission(r,p).status!=='blocked');return possible.length?'По возрасту: '+possible.map(p=>p.label).join(', ')+'. Рост нужно проверить.':'Учебные условия допуска';}
function details(r){return `<details class="ride-details" id="details-${r.id}"><summary>Условия и рост</summary><p>${r.rules?`Учебные ограничения: рост от ${r.rules.min} до ${r.rules.max} см.${r.rules.soloMin>r.rules.min?' В части возрастов и при небольшом росте нужен взрослый.':''}`:'У парка нужно уточнить ограничения по возрасту, росту и сопровождению.'}</p>${r.fictional&&state.party.length?state.party.map(p=>`<p><strong>${esc(p.label)}:</strong> ${esc((admission(r,p).reasons||[]).join(' ')||'Уточните условия перед катанием.')}</p>`).join(''):''}<p class="helper">Учебные правила не являются правилами парка. Покупка не подтверждает допуск. Работу аттракциона проверяют в день посещения. <a href="availability.html">Посмотреть учебные статусы</a>.</p>${r.rules&&state.party.length?`<details class="height-detail" id="height-${r.id}"><summary>Уточнить известный рост</summary>${state.party.map(p=>`<div class="height-row"><label for="height-${r.id}-${p.id}">${esc(p.label)}</label><div class="height-input"><input id="height-${r.id}-${p.id}" data-field="height" data-person="${p.id}" data-ride="${r.id}" type="text" inputmode="decimal" value="${p.height??''}" placeholder="Не знаю" aria-describedby="height-error-${r.id}-${p.id}"><span>см</span></div><span class="field-error" id="height-error-${r.id}-${p.id}" role="status"></span><p class="helper">${p.height===null?'Можно оставить неизвестным.':esc((admission(r,p).reasons||[]).join(' '))}</p></div>`).join('')}</details>`:''}</details>`;}
function photoLabel(r){return r.photo?.startsWith('assets/demo-')?'Учебный пример · сгенерированное изображение':'Учебные условия · фото парка';}
function photoAttrs(r,kind='card'){if(!r.fictional||!r.photo||!r.photo.startsWith('assets/demo-'))return `src="${esc(r.photo)}"`;const stem=r.photo.replace(/\.webp$/,'');const sizes=kind==='plan'?'60px':kind==='product'?'(max-width:599px) 88px, 104px':'(max-width:359px) calc(100vw - 24px), (max-width:599px) calc(100vw - 32px), (max-width:999px) calc(50vw - 34px), (max-width:1279px) calc(50vw - 225px), (max-width:1359px) calc(50vw - 240px), 440px';return `src="${esc(r.photo)}" srcset="${esc(stem)}-thumb.webp 160w, ${esc(stem)}-small.webp 400w, ${esc(r.photo)} 720w" sizes="${sizes}"`;}
function rideCard(r,i){const chosen=selected().includes(r.id);return `<article class="ride-card ${chosen?'is-selected':''}" id="ride-${r.id}">${r.photo?`<figure class="ride-visual"><div class="ride-image"><img ${photoAttrs(r)} width="560" height="350" ${i===0?'loading="eager" fetchpriority="high"':'loading="lazy"'} alt="${esc(r.fictional?'Учебный пример: '+r.name:r.name+' в Victory Park')}"></div>${r.fictional?'<figcaption class="generated-label">'+photoLabel(r)+'</figcaption>':''}</figure>`:`<div class="demo-art" data-art="${['wave','speed','orbit','tower'][i%4]}" aria-hidden="true"><span>Учебный аттракцион</span></div>`}<div class="ride-body"><h3>${esc(r.name)}</h3>${r.fictional?'':`<div class="catalog-availability" data-availability-catalog-id="${esc(r.id)}"><a class="catalog-status unknown" href="availability.html">Уточняем</a><p class="catalog-status-detail">Проверяем учебный статус.</p></div>`}<p class="age-hint">${esc(ageText(r))}</p>${admissionMarkup(r)}<div class="ride-actions">${btn('toggle-ride',chosen?'✓ В нашем списке':'В наш список',`data-ride="${r.id}" aria-pressed="${chosen}"`,'btn '+(chosen?'btn-outline':'btn-primary'))}</div>${details(r)}</div></article>`;}
function undoBanner(){return undo?`<div class="undo-banner" role="status">${esc(undo.message)} ${btn('undo','Отменить','','btn btn-text')}</div>`:'';}
function plan(){return `<aside class="plan-panel" id="plan"><h2>Наш список <span class="plan-count">${selected().length}</span></h2><p>То, что хочется попробовать. Можно решить на месте.</p>${undo&&['ride','person','reset'].includes(undo.kind)?undoBanner():''}<div class="plan-items">${selected().map(rid=>{const r=ride(rid);return `<article class="plan-item compact-plan-item">${r.photo?`<img ${photoAttrs(r,'plan')} alt="${esc(r.fictional?'Учебный пример: '+r.name:r.name+' в Victory Park')}" width="60" height="50" loading="lazy">`:'<span class="plan-symbol" aria-hidden="true">'+esc(r.symbol||'○')+'</span>'}<div><h3>${esc(r.name)}</h3><p>${r.fictional&&audience().some(p=>admission(r,p).needsCompanion&&admission(r,p).status!=='blocked')?'Только со взрослым 18+':r.rules?'Учебные условия допуска':'Условия уточняются у парка'}</p><a href="#details-${r.id}" data-open-details="${r.id}">Условия</a></div>${btn('toggle-ride','×',`data-ride="${rid}" aria-label="Убрать ${esc(r.name)} из списка"`,'btn btn-text')}</article>`;}).join('')||'<p class="empty-list">Сохраняйте понравившееся одним нажатием.</p>'}</div><a class="btn btn-primary" href="tickets.html">Выбрать билеты →</a>${state.mode==='real'?'<p class="helper">Для настоящих аттракционов продажа пока не подключена.</p>':''}</aside>`;}
function renderPicker(){let cardIndex=0;const list=displayedRides(),groups=[['calm','Спокойные впечатления'],['exciting','Острые ощущения'],['other',state.mode==='real'?'Аттракционы парка':'Ещё впечатления']];return `${hero('picker')}${family()}<div class="section-head" id="catalog"><div><h2>${state.mode==='demo'?'Что попробуем?':'Аттракционы парка'}</h2><p>${state.mode==='demo'?'Показываем учебные аттракционы по возрасту. Сопровождение видно сразу, рост можно уточнить в условиях.':'Настоящие названия и фотографии. Категории и правила пока не подтверждены.'}</p></div></div>${catalogModes()}${state.mode==='real'?'<p class="catalog-status-note">Статусы учебные и меняются вместе со страницей <a href="availability.html">«Что сейчас работает»</a>. Работает: оценка по списаниям или отметка дежурного.</p>':'<p class="catalog-status-note">Фотографии парка и статусы работы доступны во вкладке «Аттракционы парка».</p>'}${state.party.length?`<div class="chips family-filter" aria-label="Показать аттракционы">${btn('focus-person','Для нашей семьи',`data-person="family" aria-pressed="${focusPerson==='family'}"`,'chip')}${btn('focus-person','Все',`data-person="all" aria-pressed="${focusPerson==='all'}"`,'chip')}<details class="person-filter" id="person-filter"><summary>Для одного</summary><div class="chips">${state.party.map(p=>btn('focus-person',esc(p.label),`data-person="${p.id}" aria-pressed="${focusPerson===p.id}"`,'chip')).join('')}</div></details></div>`:''}<div class="content-layout"><div class="catalog-groups">${!list.length?'<div class="empty"><h3>По этим условиям вариантов нет</h3><p>Можно посмотреть весь каталог или выбрать другого участника.</p>'+btn('focus-person','Посмотреть все','data-person="all"','btn btn-outline')+'</div>':''}${groups.map(([key,title])=>{const group=list.filter(r=>(r.intensity||'other')===key);return group.length?`<section class="catalog-group"><h3 class="group-title">${title}<span>${group.length}</span></h3><div class="catalog-grid">${group.map(r=>rideCard(r,cardIndex++)).join('')}</div></section>`:'';}).join('')}</div>${plan()}</div>${demoTools()}`;}
function riderPicker(){if(!state.party.length)return `<div class="empty"><h3>Можно купить без семейного подбора</h3><p>Выберите конкретный продукт ниже. Получателя и необходимого взрослого можно выбрать прямо здесь.</p><a class="btn btn-text" href="attractions.html#family">Добавить семью</a></div>`;return `<section class="rider-section" id="riders"><h2>Кто будет кататься?</h2><p>Отметьте тех, кому выбираете катания. Необходимое сопровождение включим в цену автоматически.</p><div class="rider-choices">${state.party.map((p,i)=>btn('rider',`<span class="avatar" aria-hidden="true">${i+1}</span><span>${esc(p.label)}<small>${esc(ageLabel(p))}</small></span><span class="rider-check" aria-hidden="true">${state.riders.includes(p.id)?'✓':'○'}</span>`,`data-person="${p.id}" aria-pressed="${state.riders.includes(p.id)}"`,'rider-choice')).join('')}</div>${!state.ridersConfirmed?`<div class="btn-row">${btn('confirm-riders','Показать варианты',state.riders.length?'':'disabled','btn btn-primary')}<a class="btn btn-text" href="#direct">Выбрать товары самому</a></div>`:''}<a class="btn btn-text" href="attractions.html#family">Изменить состав семьи</a></section>`;}
function offerMarkup(o){const inc=o.includedRideIds.map(rid=>ride(rid)?.name).filter(Boolean),exc=(o.excludedRideIds||[]).map(rid=>ride(rid)?.name).filter(Boolean);return `<article class="offer"><span class="badge" data-tone="${o.id==='package'?'success':'demo'}">${o.id==='package'?'Делить между семьёй':'Личный для каждого'}</span><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p><div class="offer-price">${o.conditional?'От ':''}${money(o.total)}<small>${o.conditional?'Уточним состав перед оплатой':'За весь заказ · учебная цена'}</small></div><div class="offer-rights">${o.lines.map(l=>`<p><strong>${esc(l.productId==='unlimited'?person(l.personId)?.label||'Получатель':VP3.products[l.productId].name)}</strong>${l.productId==='unlimited'?' · 1 личный безлимит':' · '+l.quantity+' пакет'}${l.autoCompanion?'<span class="auto-line-label">Для сопровождения детей</span>':''}</p>`).join('')}</div><p class="helper">${o.id==='package'?'Всего 5 прав на компанию. Ребёнок и взрослый вместе расходуют 2 права за катание.':'Неограниченные повторы только на включённых аттракционах. Передать право другому нельзя.'}</p><details id="offer-${o.id}-terms"><summary>Что входит</summary><p>${inc.map(esc).join(' · ')}</p><p class="helper">Один день первого использования. Покупка не подтверждает допуск по росту.</p><p class="helper">${VP3.products[o.id==='package'?'package5':'unlimited'].terms.map(esc).join(' ')}</p></details>${exc.length?`<p class="offer-exclusions">Из вашего списка не входит: ${exc.map(esc).join(', ')}. Не добавляем в оплату автоматически.</p>`:''}${(o.notes||[]).filter(t=>t.startsWith('По указанному росту недоступно:')).map(t=>'<p class="offer-exclusions">'+esc(t)+'</p>').join('')}${o.conditional?'<p class="offer-exclusions">Нужны данные для окончательной цены: '+[...new Set((o.issues||[]).map(i=>esc(i.message)))].join(' ')+'</p>':''}${btn('choose-offer',o.conditional?'Собрать этот вариант':'Выбрать за '+money(o.total),`data-offer="${o.id}"`,'btn btn-primary')}</article>`;}
function recommendations(){if(!state.ridersConfirmed)return '';const rec=VP3.recommend(state);return `<section id="recommendations"><div class="section-head"><div><h2>Готовые варианты</h2><p>Это конкретный состав покупки. Ваш список интересов сохранён, объём будущих катаний выбирать не нужно.</p></div></div>${rec.offers.length?'<div class="offers">'+rec.offers.map(offerMarkup).join(''):'<div class="empty"><h3>Выберите отдельные билеты</h3><p>Для сохранённых интересов подходящего пакета нет. Нужный аттракцион можно выбрать ниже.</p><a class="btn btn-text" href="#direct">К отдельным билетам</a></div>'}${(rec.warnings||[]).filter(t=>t.startsWith('Безлимит не предложен:')).map(t=>'<p class="offer-exclusions">'+esc(t)+'</p>').join('')}${(rec.errors||[]).map(t=>note(typeof t==='string'?t:t.message,'error')).join('')}</section>`;}
function currentQty(target){return state.cart.lines.filter(l=>!l.autoCompanion&&(target==='package5'?l.productId==='package5':target.startsWith('ticket:')?l.productId==='ticket'&&l.rideId===target.slice(7)&&l.personId===ticketPersonId:target.startsWith('line:')?l.id===target.slice(5):false)).reduce((sum,l)=>sum+l.quantity,0);}
function quantity(target,n){return `<div class="quantity-choice"><span class="quantity-label">Количество ${(target==='package5'||target.startsWith('line:')&&state.cart.lines.find(l=>l.id===target.slice(5))?.productId==='package5')?'пакетов':'билетов'}</span><div class="quantity-pills" role="group" aria-label="Количество товара">${[1,2,3,4].map(q=>btn('quantity',q,`data-target="${esc(target)}" data-value="${q}" aria-pressed="${n===q}"`,'quantity-pill')).join('')}${btn('custom-quantity',n>4?String(n):'Другое',`data-target="${esc(target)}" aria-pressed="${n>4}"`,'quantity-pill')}</div>${customTarget===target?`<form class="custom-quantity-form" data-target="${esc(target)}"><label for="custom-quantity">От 1 до 20</label><div class="btn-row"><input id="custom-quantity" name="quantity" type="text" inputmode="numeric" value="${n||''}" aria-describedby="quantity-error" autocomplete="off"><button type="submit" class="btn btn-dark">Применить</button></div><span id="quantity-error" class="field-error" role="alert"></span></form>`:''}</div>`;}
function directProducts(){const recipient=person(ticketPersonId);return `<section class="direct-products" id="direct"><div class="section-head"><div><${directEntry?'h1':'h2'}>${directEntry?'Билеты, пакеты и безлимиты':'Выбрать самому'}</${directEntry?'h1':'h2'}><p>Учебная покупка · деньги не списываются.${returnMode==='real'&&state.selections.real.length?' Настоящие аттракционы сохранены в вашем списке отдельно.':''}</p></div></div><div class="product-tabs chips" aria-label="Вид продукта">${[['single','Билеты'],['package','Пакеты'],['unlimited','Безлимиты']].map(([value,label])=>btn('product-focus',label,`data-product="${value}" aria-pressed="${activeProduct===value}"`,'chip')).join('')}</div>${activeProduct==='single'?`${purchasePeople()}${VP3.demoRides.slice().sort((a,b)=>Number(state.selections.demo.includes(b.id))-Number(state.selections.demo.includes(a.id))).map(r=>{const a=recipient?admission(r,recipient):null;return `<article class="product" id="product-${r.id}"><div class="product-intro">${r.photo?`<img ${photoAttrs(r,'product')} width="104" height="104" loading="lazy" alt="Учебный пример: ${esc(r.name)}">`:''}<div><h3>${esc(r.name)}</h3>${state.selections.demo.includes(r.id)?'<p class="helper">В вашем списке</p>':''}<div class="offer-price">${money(r.price)}<small>Одно право катания</small></div></div></div>${r.photo?'<p class="generated-label">'+photoLabel(r)+'</p>':''}${a?.needsCompanion&&a.status!=='blocked'?`<div class="companion-badge"><span aria-hidden="true">18+</span><strong>Только со взрослым 18+</strong></div><p class="helper">Ребёнок + взрослый: ${money(r.price+(VP3.admissionRules?.[r.id]?.adultPrice??r.price))} за одно совместное катание. Уже выбранное право взрослого учтём.</p>`:'<p class="helper">Один билет на одно катание. Покупка не подтверждает допуск.</p>'}${a?.priceNeedsHeight?'<p class="helper">Рост уточним в заказе: от него зависит билет взрослого.</p>':''}${a?.status==='blocked'?`<p class="offer-exclusions">${esc(recipient.label)}: ${esc((a.reasons||[]).join(' '))}</p>`:recipient?quantity('ticket:'+r.id,currentQty('ticket:'+r.id)):'<a class="btn btn-outline" href="#purchase-people">Выбрать получателя выше</a>'}</article>`;}).join('')}`:activeProduct==='package'?`<article class="product"><span class="badge" data-tone="success">Общий для компании</span><h3>Пакет на 5 катаний</h3><p>5 оплаченных прав. Ребёнок и сопровождающий вместе используют 2 права за одно катание.</p><div class="offer-price">${money(VP3.products.package5.price)}</div><p class="helper">Можно делить между участниками. Это не 5 совместных катаний и не безлимит.</p><p class="helper">Входят: ${VP3.products.package5.includedRideIds.map(rid=>esc(ride(rid).name)).join(', ')}. ${esc(ride('demo-unknown').name)} не входит. Один день первого использования.</p>${quantity('package5',currentQty('package5'))}</article>`:`<article class="product"><span class="badge" data-tone="demo">Личный на день первого использования</span><h3>Безлимит</h3><div class="offer-price">${money(VP3.products.unlimited.price)}<small>Для одного человека</small></div><p>Повторы без ограничения: ${VP3.products.unlimited.includedRideIds.map(rid=>esc(ride(rid).name)).join(', ')}.</p><p class="helper">${esc(ride('demo-small').name)} и ${esc(ride('demo-unknown').name)} не входят. Передать другому нельзя.</p><p class="helper">Если ребёнку нужен взрослый, в заказ войдёт и его безлимит. Один взрослый сопровождает детей по очереди.</p>${purchasePeople()}</article>`}</section>`;}
function lineName(l){return l.productId==='ticket'?'Билет: '+(ride(l.rideId)?.name||'Аттракцион'):VP3.products[l.productId]?.name||'Товар';}
function lineRecipient(l){return l.productId==='package5'?'Общий пакет для компании':person(l.personId)?.label||l.recipientLabel||'Выберите получателя';}
function savedContext(){
  const names=state.selections.demo.map(rid=>ride(rid)?.name).filter(Boolean);
  return `<div class="saved-context">${state.party.length?`<p>${state.party.map(p=>esc(personLabel(p))).join(' · ')} <a href="attractions.html#family">Изменить семью</a></p>`:''}${names.length?`<p>В вашем списке: ${names.map(esc).join(' · ')}. <a href="attractions.html?mode=demo#plan">Изменить аттракционы</a></p>`:''}${state.selections.real.length?`<p class="helper">Аттракционы парка сохранены отдельно: ${state.selections.real.map(rid=>esc(ride(rid)?.name)).join(' · ')}. Учебные билеты на них не действуют. <a href="attractions.html?mode=real#plan">К аттракционам парка</a></p>`:''}</div>`;
}
function promotionControls(a){
  const selectedOffer=VPO.getOffer(promotion.offerId), dates=a.issues.filter(i=>i.code.startsWith('visit-'));
  return `<section class="cart-promotion" id="cart-promotion" aria-labelledby="promotion-heading"><h3 id="promotion-heading">Акция в заказе</h3><label for="cart-offer">Одно предложение для этого заказа</label><select id="cart-offer" data-field="promotion"><option value="none" ${!promotion.offerId?'selected':''}>Без предложения</option>${VPO.offers.filter(o=>o.status==='active').map(o=>`<option value="${o.id}" ${promotion.offerId===o.id?'selected':''}>${esc(o.title)}</option>`).join('')}${promotion.offerId&&(!selectedOffer||selectedOffer.status!=='active')?`<option selected value="${esc(promotion.offerId)}">${esc(selectedOffer?.title||'Неизвестное предложение')}</option>`:''}</select><a class="btn btn-text" href="offers.html">Сравнить все предложения →</a>${selectedOffer?`<p>${esc(selectedOffer.benefit)}</p>${selectedOffer.id==='weekday20'?`<div class="promotion-date" id="promotion-date"><label for="cart-visit-date">Когда придёте?</label><div class="btn-row">${btn('promo-date','Сегодня',`data-date="${VPO.getToday()}" aria-pressed="${promotion.visitDate===VPO.getToday()}"`,'btn btn-outline')}${btn('promo-date','Завтра',`data-date="${nextDay(VPO.getToday())}" aria-pressed="${promotion.visitDate===nextDay(VPO.getToday())}"`,'btn btn-outline')}</div><input type="date" id="cart-visit-date" data-field="visit-date" value="${esc(promotion.visitDate||'')}" min="${VPO.getToday()}" max="2026-11-30" aria-describedby="cart-date-help"><p id="cart-date-help" class="helper">${dates.length?dates.map(i=>esc(i.message)).join(' '):'Скидка на отдельные билеты в выбранный будний день. Пакеты и безлимиты по обычной цене.'}</p></div>`:''}${selectedOffer.id==='student15'?`<label class="promotion-check" id="promotion-student"><input id="cart-student" type="checkbox" data-field="student" ${promotion.studentAcknowledged?'checked':''}><span>Все разовые билеты в этом заказе для одного владельца действующего студенческого. Он покажет документ при получении.</span></label>`:''}<details class="order-terms"><summary>Условия предложения</summary>${selectedOffer.terms.map(t=>'<p>'+esc(t)+'</p>').join('')}</details>`:''}${a.issues.filter(i=>!i.code.startsWith('visit-')).map(i=>note(i.message,'error')).join('')}${a.applied&&state.cart.lines.some(l=>l.productId!=='ticket')&&['weekday20','student15','bonus500'].includes(promotion.offerId)?'<p class="helper">Выгода рассчитана только для разовых билетов. Пакеты и безлимиты остаются в заказе по полной цене.</p>':''}</section>`;
}
function nextDay(value){const date=new Date(value+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+1);return date.toISOString().slice(0,10);}
function promotionAction(a){
  if(a.issues.some(i=>i.code.startsWith('visit-')))return {label:'Выбрать дату',target:'cart-visit-date'};
  if(a.issues.some(i=>i.code==='student-acknowledgement-required'))return {label:'Подтвердить льготу',target:'cart-student'};
  if(a.issues.some(i=>i.code==='incompatible-product'||i.code==='bonus-threshold'))return {label:promotion.offerId==='package5'?'Добавить пакет':promotion.offerId==='unlimited'?'Выбрать получателя':'Добавить билеты',target:'direct'};
  return {label:'Проверить предложение',target:'cart-offer'};
}
function focusField(target){const el=document.getElementById(target);if(!el)return;el.scrollIntoView({block:'center',behavior:'auto'});if(!el.matches('input,select,button,a'))el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}
function orderTotals(o){return `${o.promotion?.offerId?`<p>${esc(VPO.getOffer(o.promotion.offerId)?.title||'Предложение')}${o.promotion.offerId==='weekday20'?' · '+esc(o.promotion.visitDate):''}</p>`:''}${o.discount?`<div class="price-breakdown"><span>Полная стоимость</span><strong>${money(o.subtotal)}</strong><span>Скидка</span><strong>−${money(o.discount)}</strong></div>`:''}${o.bonus&&o.status==='success'?`<p>Бонус на следующий визит: ${money(o.bonus)}. С ${esc(o.bonusValidFrom)} по ${esc(o.bonusValidUntil)}. Сейчас оплачивается полная цена.</p>`:''}`;}
function legacyRecipient(l){if(l.productId==='package5'||person(l.personId))return '';return `<div class="line-recipient-fix"><p class="helper">Для старого черновика нужно выбрать получателя, чтобы учесть сопровождение.</p><div class="chips">${state.party.map(p=>btn('assign-line-person',esc(p.label)+' · '+esc(ageLabel(p)),`data-line="${l.id}" data-person="${p.id}"`,'chip')).join('')}</div>${!state.party.length?btn('fix-recipient','Добавить получателя',`data-product="${l.productId==='unlimited'?'unlimited':'single'}"`,'btn btn-outline'):''}</div>`;}
function cart(){
  const a=VPC.calculate(state,promotion),action=promotionAction(a),extra=!state.cart.lines.length&&state.ridersConfirmed?VP3.recommend(state).offers.flatMap(o=>o.issues||[]):[],conditional=Boolean(accompaniment?.conditional);
  return `<aside class="cart-panel" id="cart"><h2 tabindex="-1" id="cart-heading">Ваш заказ</h2>${undo?.kind==='cart'?undoBanner():''}${companionControls(extra)}${!state.cart.lines.length?'<p class="empty-list">Добавьте билеты в заказ. Ваш список аттракционов сохранён.</p>':state.cart.lines.map(l=>`<article class="cart-line ${l.autoCompanion?'is-companion-line':''}"><h3>${esc(lineName(l))}</h3><p>${esc(lineRecipient(l))}</p>${l.autoCompanion?`<p class="auto-line-label">Добавлено для сопровождения</p><p class="helper">${esc(l.companionReason||'Ребёнку нужен взрослый 18+. Его оплаченное право включено в сумму.')}</p>`:''}<div class="cart-line-price"><strong>${l.quantity} шт. · ${money(l.unitPrice*l.quantity)}</strong>${!isRequiredLine(l)?btn('remove-line','Убрать',`data-line="${l.id}"`,'btn btn-text'):''}</div>${!l.autoCompanion&&l.productId!=='unlimited'?'<details class="edit-cart-quantity" id="quantity-'+l.id+'"><summary>Изменить количество</summary>'+quantity('line:'+l.id,l.quantity)+'</details>':l.productId==='unlimited'?'<p class="helper">1 личное право · день первого использования</p>':''}${!l.autoCompanion&&isRequiredLine(l)?'<p class="helper">Это право нужно для сопровождения. Чтобы убрать его, измените детскую покупку или сопровождающего.</p>':''}${legacyRecipient(l)}</article>`).join('')}${(accompaniment?.notes||[]).filter(t=>!t.includes('рост')&&!t.includes('Один взрослый безлимит')).map(t=>'<p class="accompaniment-note">'+esc(t)+'</p>').join('')}${promotion.offerId?promotionControls(a):'<details class="optional-promotion" id="optional-promotion"><summary>Добавить акцию</summary>'+promotionControls(a)+'</details>'}${state.cart.lines.length?`${a.discount?`<div class="price-breakdown"><span>Полная стоимость</span><strong>${money(a.subtotal)}</strong><span>Скидка сейчас</span><strong>−${money(a.discount)}</strong></div>`:''}<div class="total"><span>${conditional?'Пока от':a.applied?'К оплате':'Итого'}</span><strong>${money(a.payable)}</strong></div>${conditional?'<p class="helper">Сумма изменится после уточнения получателя или сопровождения. Оплата пока недоступна.</p>':''}${a.bonus?`<p>+${money(a.bonus)} на следующий визит, с ${a.bonusValidFrom} по ${a.bonusValidUntil}. Сейчас платите полную цену.</p>`:''}${a.excludedRideIds?.length?`<p class="offer-exclusions">Не входят из списка: ${a.excludedRideIds.map(rid=>esc(ride(rid)?.name)).join(', ')}. Можно купить отдельно.</p>`:''}<details class="order-terms" id="order-terms"><summary>Условия заказа</summary><p>${a.applied&&promotion.offerId==='weekday20'?'Разовые билеты действуют '+esc(promotion.visitDate)+'. Остальные продукты действуют один день первого использования.':'Все продукты действуют один день первого использования в учебной модели.'} Парк эти условия ещё не утвердил.</p><p>Сопровождение оплачивается отдельным правом. Пакет расходует по одному праву за каждого участника, безлимит ребёнка требует подходящий безлимит взрослого. Покупка не гарантирует допуск.</p></details><div id="checkout-errors" role="alert">${formError?note(formError,'error'):''}${a.errors.map(e=>note(typeof e==='string'?e:e.message,'error')).join('')}</div>${a.warnings.length?`<details class="order-terms" id="order-warnings"><summary>Ограничения и допуск</summary>${a.warnings.map(e=>'<p>'+esc(typeof e==='string'?e:e.message)+'</p>').join('')}</details>`:''}${a.issues.length?`${btn('promo-fix',action.label,`data-target="${action.target}"`,'btn btn-primary pay-button')}${btn('remove-promotion','Продолжить без предложения','','btn btn-outline pay-button')}`:`<button type="button" class="btn btn-primary pay-button" data-action="pay" ${busy||!a.canCheckout?'disabled':''}>${busy?'Проверяем заказ…':conditional?'Уточните данные выше':'Демо-оплата · '+money(a.payable)}</button>`}<p class="helper">Деньги не списываются. Билеты сразу, без регистрации и контакта.</p><details class="demo-scenarios"><summary>Проверить другой исход оплаты</summary><label for="scenario">Учебный ответ оплаты</label><select id="scenario" data-field="scenario">${[['success','Успех'],['declined','Отклонено'],['pending','Результат неизвестен'],['issuance','Оплачено, выдача задержана']].map(([v,l])=>`<option value="${v}" ${v===scenario?'selected':''}>${l}</option>`).join('')}</select></details>`:''}</aside>`;
}
function ticketCards(o){return VPC.issuedItems(o).map(t=>`<article class="demo-ticket"><div class="ticket-top"><span>VICTORY PARK</span><strong>ОБРАЗЕЦ</strong></div><h3>${esc(t.name)}</h3><p><strong>${esc(t.recipientLabel)}</strong></p><p>${esc(t.validity)}</p><p>${t.remaining===null?'Повторы без лимита на включённых аттракционах':t.remaining+' прав на катания'}</p><p class="helper">${t.includedNames.map(esc).join(' · ')}</p><details><summary>Условия этого образца</summary><ul>${t.terms.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul></details><p class="ticket-code">${esc(t.code)}</p><p class="ticket-demo">Не действует для прохода. Деньги не списывались.</p></article>`).join('');}
function receipt(){const labels={success:['Ваши билеты готовы','Все образцы доступны сразу. Контакт не требуется.'],declined:['Оплата отклонена','В учебном сценарии получен окончательный отказ. Состав заказа сохранён.'],pending:['Проверяем результат оплаты','Результат пока неизвестен. Повторная оплата заблокирована.'],issuance:['Оплачено. Готовим билеты','В учебном сценарии оплата подтверждена. Повторять её не нужно.']};return `<section class="receipt" id="receipt"><span class="badge" data-tone="demo">Демонстрация · ${esc(order.id)}</span><h1 id="result-heading" tabindex="-1">${labels[order.status][0]}</h1><p>${labels[order.status][1]}</p>${orderTotals(order)}<ul class="receipt-lines">${order.lines.map(l=>`<li>${esc(l.name)} × ${l.quantity}${l.personId||l.productId==='unlimited'?' · '+esc(l.recipientLabel):''}</li>`).join('')}</ul><div class="total"><span>Сумма заказа</span><strong>${money(order.total)}</strong></div>${order.status==='success'?`${btn('save-tickets','Сохранить все билеты','','btn btn-primary')}<p class="helper">Один HTML-файл. Открывается без интернета.</p><div class="demo-ticket-grid">${ticketCards(order)}</div><details class="copy-section" id="copy-section"><summary>Получить копию на почту</summary><p>Необязательно. В прототипе письмо не отправляется, адрес не сохраняется.</p><form id="copy-form" novalidate><div class="field"><label for="copy-email">Электронная почта</label><input type="email" id="copy-email" name="email" inputmode="email" autocomplete="off" aria-describedby="copy-status"></div><button class="btn btn-outline" type="submit">Проверить получение копии</button><p id="copy-status" role="status">${esc(copyStatus)}</p></form></details>`:`<ul>${order.lines.map(l=>`<li>${esc(l.name)} × ${l.quantity} · ${esc(l.recipientLabel)}</li>`).join('')}</ul>`}<div class="btn-row receipt-actions">${['pending','issuance'].includes(order.status)?btn('resolve-order',order.status==='pending'?'Проверить статус этого заказа':'Проверить готовность билетов','','btn btn-primary'):btn('new-order',order.status==='declined'?'Вернуться к заказу':'Собрать другой заказ','','btn btn-outline')}<a class="btn btn-text" href="${pickerReturn()}">К нашим аттракционам</a>${state.selections.real.length?'<a class="btn btn-text" href="attractions.html?mode=real#plan">К аттракционам парка</a>':''}</div><p class="helper">${storageAvailable?'Образцы сохранены только в этом браузере.':'Сохранение в браузере недоступно. Скачайте образцы сейчас.'}</p></section>`;}
function renderTickets(){if(order)return receipt();if(directEntry)return `<section class="direct-entry-head"><a class="btn btn-text" href="${pickerReturn()}">← К нашим аттракционам</a></section>${savedContext()}<div class="buy-layout direct-entry-layout"><div>${directProducts()}</div>${cart()}</div>${demoTools()}`;return `${hero('tickets')}${state.mode==='real'?`<section class="empty"><h2>Ваш список сохранён</h2><p>Для настоящих аттракционов онлайн-продукты и правила пока не подтверждены. Семья и выбранные аттракционы останутся здесь.</p><a class="btn btn-outline" href="attractions.html#plan">Вернуться к списку</a><p class="helper">Учебную покупку можно включить в описании прототипа ниже. Она не продаёт билеты на реальные аттракционы.</p></section>${demoTools()}`:`${riderPicker()}${selected().length?`<p class="saved-summary">В вашем списке: ${selected().map(rid=>esc(ride(rid)?.name)).join(' · ')}. <a href="attractions.html#plan">Изменить</a></p>`:''}<div class="buy-layout"><div>${recommendations()}${directProducts()}</div>${cart()}</div>${demoTools()}`}`;}
function render(){syncCompanions();if(!order)save();if(!person(ticketPersonId)){const selectedPeople=state.riders.map(person).filter(Boolean),children=state.party.filter(p=>p.role==='child');ticketPersonId=(selectedPeople.length===1?selectedPeople[0]:state.party.length===1?state.party[0]:children.length===1?children[0]:null)?.id||'';}const active=document.activeElement,activeId=active?.id,ds=active?.dataset?{...active.dataset}:null;const openIds=[...document.querySelectorAll('#app details[open]')].map(d=>d.id).filter(x=>x&&x!=='family');document.body.dataset.mode=state.mode;document.body.classList.toggle('family-editing',document.body.dataset.page==='picker'&&familyOpen);$('#app').innerHTML=(warning?note(warning,'error'):'')+(state._issues?.length?note('Сохранённые данные частично повреждены. Проверьте семью и заказ; при необходимости очистите выбор в описании прототипа.','error'):'')+(document.body.dataset.page==='picker'?renderPicker():renderTickets());for(const did of openIds){const d=document.getElementById(did);if(d)d.open=true;}$('#family')?.addEventListener('toggle',e=>{if(e.target.isConnected){familyOpen=e.target.open;document.body.classList.toggle('family-editing',document.body.dataset.page==='picker'&&familyOpen);}});const count=state.cart.lines.reduce((n,l)=>n+l.quantity,0);if($('#cart-count'))$('#cart-count').textContent=count?' ('+count+')':'';document.querySelectorAll('[data-mobile-cart-count]').forEach(el=>el.textContent=count?' ('+count+')':'');$('#mobile').innerHTML=order?'':`<div class="mobile-bar"><div><strong>${document.body.dataset.page==='picker'?selected().length+' в списке':(accompaniment?.conditional?'От ':'')+money(VPC.calculate(state,promotion).payable)}</strong><small>${document.body.dataset.page==='picker'?'Сохранённое для семьи':accompaniment?.conditional?'Сумма после уточнения':'Включая сопровождение'}</small></div><a class="btn btn-primary" href="${document.body.dataset.page==='picker'?'#plan':'#cart'}">${document.body.dataset.page==='picker'?'Наш список':'К заказу'}</a></div>`;if(document.body.dataset.page==='tickets'&&state.mode==='real'&&!order){$('#mobile').innerHTML='<div class="mobile-bar"><div><strong>Список сохранён</strong><small>Настоящие аттракционы</small></div><a class="btn btn-primary" href="attractions.html#plan">К списку</a></div>';}if(activeId&&document.getElementById(activeId))document.getElementById(activeId).focus({preventScroll:true});else if(ds?.action){const match=[...document.querySelectorAll('[data-action]')].find(el=>Object.entries(ds).every(([k,v])=>el.dataset[k]===v));match?.focus({preventScroll:true});}document.dispatchEvent(new Event('vp:catalog-rendered'));}
function addPerson(role){if(state.party.length>=8)return;const p={id:id(),label:(role==='adult'?'Взрослый ':'Ребёнок ')+(Math.max(0,...state.party.filter(p=>p.role===role).map(p=>Number(p.label.match(/\d+$/)?.[0])||0))+1),role,age:role==='adult'?18:null,height:null};state.party.push(p);familyOpen=true;agePerson=role==='child'?p.id:'';update();requestAnimationFrame(()=>$('#person-'+p.id)?.scrollIntoView({block:'nearest',behavior:'smooth'}));}
function clearIssues(){state._issues=[];formError='';}
function commitCart(lines,message){undo={kind:'cart',message:'Предыдущий состав заказа можно вернуть.',lines:clone(state.cart.lines)};state.cart={lines};clearIssues();update(message);}
function setQuantity(target,n){if(!Number.isInteger(n)||n<1||n>20)return false;if(target.startsWith('ticket:')&&!person(ticketPersonId))return false;const lines=clone(state.cart.lines);let line=lines.find(l=>!l.autoCompanion&&(target==='package5'?l.productId==='package5':target.startsWith('ticket:')?l.productId==='ticket'&&l.rideId===target.slice(7)&&l.personId===ticketPersonId:l.id===target.slice(5)));if(line)line.quantity=n;else{const productId=target==='package5'?'package5':'ticket',rid=productId==='ticket'?target.slice(7):null;if(!rid&&productId==='ticket')return false;line={id:id(),productId,rideId:rid,personId:productId==='ticket'?ticketPersonId:null,recipientKey:null,quantity:n,unitPrice:productId==='ticket'?ride(rid).price:VP3.products.package5.price};lines.push(line);}customTarget='';commitCart(lines,'Состав и сопровождение пересчитаны.');return true;}
function directPass(pId){if(!state.riders.includes(pId))state.riders.push(pId);ticketPersonId=pId;const current=state.cart.lines.find(l=>l.productId==='unlimited'&&l.personId===pId);if(current&&isRequiredLine(current))return;if(person(pId)?.role==='child'&&person(pId).age===null)agePerson=pId;commitCart(current?state.cart.lines.filter(l=>l.id!==current.id):[...state.cart.lines,{id:id(),productId:'unlimited',rideId:null,personId:pId,recipientKey:null,quantity:1,unitPrice:VP3.products.unlimited.price}],current?'Безлимит удалён.':'Безлимит и необходимое сопровождение добавлены.');}
function purchaseAdd(role,companion=false){if(state.party.length>=8)return;const p={id:id(),label:(role==='adult'?'Взрослый ':'Ребёнок ')+(Math.max(0,...state.party.filter(x=>x.role===role).map(x=>Number(x.label.match(/\d+$/)?.[0])||0))+1),role,age:role==='adult'?18:null,height:null};state.party.push(p);if(companion){state.companionId=p.id;update('Взрослый добавлен для сопровождения.');jump('#companion-controls');return;}ticketPersonId=p.id;agePerson=role==='child'?p.id:'';const missing=state.cart.lines.filter(l=>l.productId!=='package5'&&!l.personId);if(missing.length===1)missing[0].personId=p.id;else if(activeProduct==='unlimited'){state.cart.lines.push({id:id(),productId:'unlimited',rideId:null,personId:p.id,recipientKey:null,quantity:1,unitPrice:VP3.products.unlimited.price});if(!state.riders.includes(p.id))state.riders.push(p.id);}update('Получатель добавлен.');jump('#purchase-people');}
async function pay(){if(busy||order)return;const a=VPC.calculate(state,promotion);if(!a.canCheckout){formError='Проверьте состав и получателей заказа.';render();jump('#checkout-errors');return;}busy=true;render();const run=async()=>{try{const other=VPC.validateOrder(JSON.parse(localStorage.getItem(ORDER)||'null'));if(other){order=other;busy=false;render();return;}}catch{}order=VPC.snapshotOrder(state,promotion,'DEMO-'+id(),'pending');if(!order){busy=false;formError='Не удалось создать образец. Проверьте заказ.';render();return;}saveOrder();render();await new Promise(resolve=>setTimeout(resolve,300));order.status=scenario;saveOrder();busy=false;render();window.scrollTo({top:0});$('#result-heading')?.focus({preventScroll:true});announce('Статус заказа обновлён.');};try{if(navigator.locks?.request)await navigator.locks.request(LOCK,run);else{busy=false;formError='В этом браузере недоступна защита заказа между вкладками. Откройте прототип в современном браузере.';render();}}catch{busy=false;warning='Не удалось завершить проверку. Если заказ создан, проверяйте его статус.';render();}}
function saveTickets(){if(!order||order.status!=='success')return;const html=`<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Демо-билеты ${esc(order.id)}</title><style>body{font:16px/1.5 Arial,sans-serif;color:#2f2e7d;max-width:850px;margin:24px auto;padding:20px}h1{font-size:30px}h3{font-size:22px}.demo-ticket{border:2px solid #2f2e7d;border-radius:16px;padding:22px;margin:18px 0;break-inside:avoid}.ticket-top{display:flex;justify-content:space-between;gap:15px;font-size:12px}.ticket-code{font:13px monospace;overflow-wrap:anywhere}.ticket-demo{font-weight:bold}details{margin:14px 0}</style><h1>Ваши демо-билеты</h1><p>${esc(order.id)} · ${money(order.total)}</p><p>Образцы не действуют для прохода. Деньги не списывались.</p>${ticketCards(order).replaceAll('<details>','<details open>')}${orderTotals(order)}<p>Учебные условия, не утверждённая оферта парка.</p></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=order.id+'-tickets.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Полный комплект подготовлен для сохранения.');}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-open-details]');if(detail){e.preventDefault();const d=$('#details-'+detail.dataset.openDetails);if(d){d.open=true;jump('#details-'+detail.dataset.openDetails);}return;}const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;if(busy)return;
if(act==='ticket-person'){ticketPersonId=b.dataset.person;agePerson=person(ticketPersonId)?.age===null&&person(ticketPersonId)?.role==='child'?ticketPersonId:'';render();return;}
if(act==='purchase-add-adult'||act==='purchase-add-child'||act==='purchase-add-companion'){purchaseAdd(act==='purchase-add-child'?'child':'adult',act==='purchase-add-companion');return;}
if(act==='choose-companion'){state.companionId=b.dataset.person;state.companionAutoSelected=false;clearIssues();update('Сопровождающий выбран для всего заказа.');return;}
if(act==='assign-line-person'){const line=state.cart.lines.find(l=>l.id===b.dataset.line);if(line){line.personId=b.dataset.person;line.recipientKey=null;ticketPersonId=b.dataset.person;if(person(ticketPersonId)?.role==='child'&&person(ticketPersonId).age===null)agePerson=ticketPersonId;clearIssues();update('Получатель выбран. Сопровождение пересчитано.');}return;}
if(act==='add-adult'||act==='add-child'){addPerson(act==='add-adult'?'adult':'child');return;}
if(act==='collapse-family'){agePerson='';familyOpen=false;render();jump('#catalog');return;}
if(act==='edit-age'){agePerson=agePerson===b.dataset.person?'':b.dataset.person;render();if(agePerson)requestAnimationFrame(()=>$('#person-'+agePerson)?.scrollIntoView({block:'nearest',behavior:'smooth'}));return;}
if(act==='choose-age'){const p=person(b.dataset.person);if(!p||p.role!=='child')return;const value=b.dataset.value;if(value!=='unknown'&&(!Number.isInteger(Number(value))||Number(value)<0||Number(value)>17))return;p.age=value==='unknown'?null:Number(value);agePerson='';clearIssues();update('Возраст сохранён.');$('#age-'+p.id)?.focus({preventScroll:true});return;}
if(act==='remove-person'){undo={kind:'person',message:'Участник удалён.',state:clone(state)};const pid=b.dataset.person;if(agePerson===pid)agePerson='';state.party=state.party.filter(p=>p.id!==pid);state.riders=state.riders.filter(x=>x!==pid);state.cart.lines=state.cart.lines.filter(l=>l.personId!==pid);if(!state.riders.length)state.ridersConfirmed=false;clearIssues();update('Участник и его личные товары удалены. Можно отменить.');return;}
if(act==='focus-person'){focusPerson=b.dataset.person;render();return;}
if(act==='toggle-ride'){const rid=b.dataset.ride,ids=selected(),exists=ids.includes(rid);undo=exists?{kind:'ride',message:'Аттракцион удалён из списка.',ride:rid,mode:state.mode}:null;state.selections[state.mode]=exists?ids.filter(x=>x!==rid):[...ids,rid];update(exists?'Удалено. Можно отменить.':'Сохранено в нашем списке.');return;}
if(act==='mode'){state.mode=b.dataset.mode;focusPerson='family';undo=null;update('Набор данных изменён. Ваши списки сохранены отдельно.');return;}
if(act==='sample'){undo={kind:'sample',message:'Загружен пример. Свой выбор можно вернуть.',state:clone(state),promotion:clone(promotion)};promotion=VPC.normalizePromotion(null);savePromotion();state=VP3.sampleState();familyOpen=false;agePerson='';focusPerson='family';update('Загружен пример.');return;}
if(act==='reset-state'){undo={kind:'reset',message:'Выбор очищен.',state:clone(state),promotion:clone(promotion)};promotion=VPC.normalizePromotion(null);savePromotion();state=VP3.emptyState();familyOpen=true;agePerson='';update('Выбор очищен. Можно отменить.');return;}
if(act==='undo'){if(!undo)return;if(undo.kind==='ride')state.selections[undo.mode]=[...new Set([...state.selections[undo.mode],undo.ride])];else if(undo.kind==='cart')state.cart.lines=undo.lines;else if(undo.state)state=undo.state;if(undo.promotion){promotion=undo.promotion;savePromotion();}undo=null;update('Изменение отменено.');return;}
if(act==='rider'){const pid=b.dataset.person;state.riders=state.riders.includes(pid)?state.riders.filter(x=>x!==pid):[...state.riders,pid];update('Катающиеся изменены. Состав уже выбранного заказа можно проверить ниже.');return;}
if(act==='confirm-riders'){if(!state.riders.length)return;state.ridersConfirmed=true;update();jump('#recommendations');return;}
if(act==='choose-offer'){const offer=VP3.recommend(state).offers.find(o=>o.id===b.dataset.offer);if(offer){commitCart(clone(offer.lines),'Вариант выбран.');jump('#cart');}return;}
if(act==='fix-recipient'){activeProduct=b.dataset.product;render();jump('#purchase-people');return;}
if(act==='product-focus'){activeProduct=b.dataset.product;customTarget='';render();return;}
if(act==='quantity'){setQuantity(b.dataset.target,Number(b.dataset.value));return;}
if(act==='custom-quantity'){customTarget=b.dataset.target;render();$('#custom-quantity')?.focus();return;}
if(act==='remove-line'){const current=state.cart.lines.find(l=>l.id===b.dataset.line);if(current&&isRequiredLine(current))return;commitCart(state.cart.lines.filter(l=>l.id!==b.dataset.line),'Товар удалён. Можно отменить.');return;}
if(act==='direct-pass'){directPass(b.dataset.person);return;}
if(act==='promo-date'){promotion.visitDate=b.dataset.date;savePromotion();render();focusField('cart-visit-date');return;}
if(act==='promo-fix'){if(b.dataset.target==='direct'){const product=VPO.getOffer(promotion.offerId)?.productIds[0];activeProduct=product==='package5'?'package':product==='unlimited'?'unlimited':'single';render();}focusField(b.dataset.target);return;}
if(act==='remove-promotion'){promotion.offerId=null;savePromotion();render();announce('Предложение убрано. Все билеты сохранены.');return;}
if(act==='pay'){pay();return;}
if(act==='save-tickets'){saveTickets();return;}
if(act==='resolve-order'){order.status=order.status==='pending'?'issuance':'success';saveOrder();render();announce('Обновлён тот же демо-заказ.');return;}
if(act==='new-order'){if(order?.status==='success'){state.cart={lines:[]};promotion=VPC.normalizePromotion(null);savePromotion();}order=null;saveOrder();if(directEntry)state.mode='demo';clearIssues();update();if(directEntry)jump('#direct');return;}
});
document.addEventListener('change',e=>{const el=e.target,field=el.dataset.field;if(field==='scenario'){scenario=el.value;return;}if(['promotion','visit-date','student'].includes(field)){if(field==='promotion'){const next=el.value==='none'?null:el.value;if(next!==promotion.offerId)promotion.studentAcknowledged=false;promotion.offerId=next;}if(field==='visit-date')promotion.visitDate=el.value||null;if(field==='student')promotion.studentAcknowledged=el.checked;savePromotion();render();announce('Предложение сохранено. Состав заказа не изменён.');return;}if(field!=='height')return;const p=person(el.dataset.person);if(!p)return;const raw=el.value.trim().replace(',','.'),n=Number(raw),valid=raw===''||(/^\d+(\.\d+)?$/.test(raw)&&n>=40&&n<=250);const error=document.getElementById(el.getAttribute('aria-describedby'))||document.getElementById('height-error-'+el.dataset.ride+'-'+p.id);if(!valid){el.setAttribute('aria-invalid','true');if(error)error.textContent='Укажите рост от 40 до 250 см или оставьте пустым.';return;}p.height=raw===''?null:n;el.removeAttribute('aria-invalid');if(error)error.textContent='';clearIssues();update('Рост сохранён. Условия и цена пересчитаны.');});
document.addEventListener('submit',e=>{const f=e.target;if(f.matches('.custom-quantity-form')){e.preventDefault();const raw=f.elements.quantity.value.trim(),n=Number(raw);if(!/^\d+$/.test(raw)||!setQuantity(f.dataset.target,n))$('#quantity-error').textContent='Введите целое число от 1 до 20. Заказ не изменён.';return;}if(f.id==='direct-person-form'){e.preventDefault();const name=f.elements.name.value.trim();if(!name){$('#recipient-error').textContent='Укажите имя получателя.';return;}if(state.party.some(p=>p.label.toLocaleLowerCase()===name.toLocaleLowerCase())){$('#recipient-error').textContent='Такой участник уже есть. Выберите его выше.';return;}if(state.party.length>=8){$('#recipient-error').textContent='В прототипе до восьми участников. Выберите существующего.';return;}const p={id:id(),label:name,role:f.elements.role.value==='child'?'child':'adult',age:null,height:null};state.party.push(p);directPass(p.id);return;}if(f.id==='copy-form'){e.preventDefault();const input=$('#copy-email');if(!input.value.trim()||!input.checkValidity()){copyStatus='Проверьте адрес электронной почты.';$('#copy-status').textContent=copyStatus;input.setAttribute('aria-invalid','true');return;}input.removeAttribute('aria-invalid');copyStatus='Проверка завершена. В прототипе письмо не отправлено, адрес не сохранён. Билеты доступны выше.';$('#copy-status').textContent=copyStatus;input.value='';}});
window.addEventListener('storage',e=>{if(e.key===PROMO&&!busy){try{promotion=VPC.normalizePromotion(JSON.parse(e.newValue||'null'));render();}catch{}}if(e.key===KEY&&!busy){try{state=VP3.sanitizeState(JSON.parse(e.newValue||'null'));render();announce('Выбор обновлён в другой вкладке.');}catch{}}if(e.key===ORDER){try{order=VPC.validateOrder(JSON.parse(e.newValue||'null'));render();}catch{}}});
window.addEventListener('pagehide',()=>{try{history.replaceState({...history.state,vp3scroll:window.scrollY,vp3Mode:state.mode},'');}catch{}});
window.addEventListener('pageshow',e=>{if(e.persisted){try{promotion=VPC.normalizePromotion(JSON.parse(localStorage.getItem(PROMO)||'null'));state=VP3.sanitizeState(JSON.parse(localStorage.getItem(KEY)||'null'));order=VPC.validateOrder(JSON.parse(localStorage.getItem(ORDER)||'null'));if(document.body.dataset.page==='picker'&&['real','demo'].includes(history.state?.vp3Mode))state.mode=history.state.vp3Mode;if(document.body.dataset.page==='tickets'&&directEntry&&!order)state.mode='demo';save();render();}catch{}}});
const params=new URLSearchParams(location.search);if(params.has('product'))activeProduct=['single','package','unlimited'].includes(params.get('product'))?params.get('product'):'single';if(location.hash==='#family')familyOpen=true;if(document.body.dataset.page==='picker'&&['real','demo'].includes(params.get('mode'))){state.mode=params.get('mode');save();}const deepRide=ride(params.get('ride'));if(deepRide){state.mode=deepRide.fictional?'demo':'real';save();}
if(document.body.dataset.page==='tickets'){
  if(params.has('offer')){const next=params.get('offer')==='none'?null:params.get('offer');if(next!==promotion.offerId)promotion.studentAcknowledged=false;promotion.offerId=next;}
  if(params.has('date'))promotion.visitDate=params.get('date')||null;
  if(params.has('student'))promotion.studentAcknowledged=params.get('student')==='1';
  if(!order&&!state.cart.lines.length&&params.has('legacyProduct')){
    const product=params.get('legacyProduct'),rid=params.get('legacyRide'),n=Number(params.get('legacyQty'));
    if(['ticket','package5','unlimited'].includes(product)&&Number.isInteger(n)&&n>=1&&n<=20&&(product!=='ticket'||VP3.demoRides.some(r=>r.id===rid))){
      state.cart.lines=Array.from({length:product==='unlimited'?n:1},(_,i)=>({id:id(),productId:product,rideId:product==='ticket'?rid:null,personId:null,recipientKey:product==='unlimited'?'legacy-recipient-'+(i+1):null,quantity:product==='unlimited'?1:n,unitPrice:product==='ticket'?ride(rid).price:VP3.products[product].price}));
      state.mode='demo';save();
    }
  }
  savePromotion();['offer','date','student','legacyProduct','legacyRide','legacyQty'].forEach(k=>params.delete(k));
  try{history.replaceState(history.state,'',location.pathname+(params.size?'?'+params.toString():'')+location.hash);}catch{}
}
if(document.body.dataset.page==='tickets'){directEntry=params.has('product')||params.get('from')==='real'||location.hash==='#direct'||state.mode==='real'||!state.party.length;returnMode=params.get('from')==='real'||state.mode==='real'?'real':'';if(directEntry){if(!params.has('product')){activeProduct='single';params.set('product','single');}if(returnMode==='real')params.set('from','real');try{history.replaceState(history.state,'',location.pathname+'?'+params.toString()+location.hash);}catch{}if(!order){state.mode='demo';save();}}}

render();
if(deepRide){const d=$('#details-'+deepRide.id);if(d)d.open=true;jump('#ride-'+deepRide.id);}else if(order&&document.body.dataset.page==='tickets')window.scrollTo({top:0});else if(location.hash==='#cart'&&state.cart.lines.length)jump('#cart');else if(directEntry)jump('#direct');else if(location.hash)jump(location.hash);else if(history.state?.vp3scroll)requestAnimationFrame(()=>window.scrollTo(0,history.state.vp3scroll));
if(window.visualViewport){const setKeyboard=()=>document.body.classList.toggle('keyboard-open',innerHeight-window.visualViewport.height>150&&/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''));window.visualViewport.addEventListener('resize',setKeyboard);document.addEventListener('focusout',()=>requestAnimationFrame(setKeyboard));}
window.VP3UI={getState:()=>clone(state),getOrder:()=>clone(order)};
})();
